/* Host unit tests for the openmeshd discovery protocol. */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <unistd.h>

#include <sodium.h>

#include "identity.h"
#include "discovery.h"
#include "find_node_hex.h"	/* generated by host-build.sh */

static int checks;
static int new_calls;
static char last_new_hex[OM_ID_HEX_LEN];

#define CHECK(x) do { \
	checks++; \
	if (!(x)) { \
		fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #x); \
		exit(1); \
	} \
} while (0)

static void count_new(struct om_disc *d, const struct om_node_info *n,
		      void *priv)
{
	(void)d;
	(void)priv;
	new_calls++;
	om_id_to_hex(n->id, last_new_hex);
}

static void mkident(struct om_identity *id, const char *tag)
{
	char tmpl[64];

	snprintf(tmpl, sizeof(tmpl), "/tmp/omdisc-%s-XXXXXX", tag);
	CHECK(mkdtemp(tmpl) != NULL);
	CHECK(om_identity_init(id, tmpl) == 0);
}

static void mkcfg(struct om_disc_cfg *c)
{
	memset(c, 0, sizeof(*c));
	c->interval = 10;
	c->listen_port = 0;	/* ephemeral: logic tests need no socket */
	c->dest_port = 0;
	strcpy(c->dest_addr, "127.0.0.1");
	strcpy(c->role, "auto");
	strcpy(c->model, "test-model");
	strcpy(c->fw, "test-fw");
}

int main(void)
{
	struct om_identity ia, ib;
	struct om_disc da, db;
	struct om_disc_cfg ca;
	uint8_t pkt[OM_PKT_MAX];
	size_t n;
	time_t now = time(NULL);

	mkident(&ia, "a");
	mkident(&ib, "b");

	mkcfg(&ca);
	CHECK(om_disc_init(&da, &ca, &ia) == 0);
	da.on_new = count_new;

	/* 1. build a valid packet */
	n = om_disc_build_packet(&da, pkt, sizeof(pkt), (uint64_t)now);
	CHECK(n >= OM_MIN_LEN && n <= OM_PKT_MAX);

	/* 2. valid packet accepted, node table filled, callback fired */
	CHECK(om_disc_handle_packet(&da, pkt, n, "192.168.40.9", now) == 0);
	CHECK(da.n_nodes == 1);
	CHECK(new_calls == 1);
	CHECK(strcmp(da.nodes[0].role, "auto") == 0);
	CHECK(strcmp(da.nodes[0].model, "test-model") == 0);
	CHECK(strcmp(da.nodes[0].fw, "test-fw") == 0);
	CHECK(strcmp(da.nodes[0].addr, "192.168.40.9") == 0);

	/* 3. exact replay rejected (nonce ring), no duplicate callback */
	CHECK(om_disc_handle_packet(&da, pkt, n, "192.168.40.9", now) == -1);
	CHECK(da.n_nodes == 1);
	CHECK(new_calls == 1);

	/* 4. fresh nonce, fresh ts -> refresh accepted, still one node */
	{
		size_t n2 = om_disc_build_packet(&da, pkt, sizeof(pkt),
						 (uint64_t)now);
		CHECK(n2 >= OM_MIN_LEN);
		CHECK(om_disc_handle_packet(&da, pkt, n2, "192.168.40.9",
					    now) == 0);
		CHECK(da.n_nodes == 1);
		CHECK(new_calls == 1);
	}

	/* 5. tampered body rejected (signature covers it) */
	pkt[110] ^= 0x01;
	CHECK(om_disc_handle_packet(&da, pkt, n, "192.168.40.9", now) == -1);
	pkt[110] ^= 0x01;

	/* 6. tampered pubkey rejected (id != SHA256(pk)) */
	pkt[75] ^= 0x01;
	CHECK(om_disc_handle_packet(&da, pkt, n, "192.168.40.9", now) == -1);
	pkt[75] ^= 0x01;

	/* 7. stale timestamp rejected */
	{
		uint8_t old[OM_PKT_MAX];
		size_t o = om_disc_build_packet(&da, old, sizeof(old),
						(uint64_t)now - 300);
		CHECK(o >= OM_MIN_LEN);
		CHECK(om_disc_handle_packet(&da, old, o, "192.168.40.9",
					    now) == -1);
	}

	/* 8. bad magic / short buffer rejected */
	pkt[0] = 'X';
	CHECK(om_disc_handle_packet(&da, pkt, n, "x", now) == -1);
	pkt[0] = 'O';
	CHECK(om_disc_handle_packet(&da, pkt, 10, "x", now) == -1);
	CHECK(om_disc_handle_packet(&da, pkt, OM_PKT_MAX + 1, "x", now) == -1);

	/* 9. correctly signed body without a role field is rejected */
	{
		uint8_t p2[OM_PKT_MAX];
		const char *body = "{\"x\":\"y\"}";
		size_t bl = strlen(body) + 1;
		size_t total = OM_HDR_LEN + bl + OM_SIG_LEN;

		memcpy(p2, "OMAN", 4);
		p2[4] = 1;
		for (int i = 0; i < 8; i++)
			p2[5 + i] = (uint8_t)(((uint64_t)now >> (56 - 8 * i)) & 0xff);
		randombytes_buf(p2 + 13, 24);
		memcpy(p2 + 37, ia.id, OM_ID_LEN);
		memcpy(p2 + 69, ia.pk, OM_PK_LEN);
		memcpy(p2 + OM_HDR_LEN, body, bl);
		CHECK(om_identity_sign(&ia, p2 + 5,
				       total - OM_SIG_LEN - 5,
				       p2 + total - OM_SIG_LEN) == 0);
		CHECK(om_disc_handle_packet(&da, p2, total, "192.168.40.9",
					    now) == -1);
	}

	/* 10. a second node is added, callback fires for it */
	{
		struct om_disc_cfg cb2 = ca;

		CHECK(om_disc_init(&db, &cb2, &ib) == 0);
		db.on_new = count_new;
		n = om_disc_build_packet(&db, pkt, sizeof(pkt), (uint64_t)now);
		CHECK(n >= OM_MIN_LEN);
		CHECK(om_disc_handle_packet(&da, pkt, n, "192.168.40.10",
					    now) == 0);
		CHECK(da.n_nodes == 2);
		CHECK(new_calls == 2);
		om_disc_free(&db);
	}

	/* 11. GC removes stale nodes */
	om_disc_tick(&da, now + 120);
	CHECK(da.n_nodes == 0);

	/* 12. table-full eviction: 32 nodes, 33rd evicts the oldest */
	{
		struct om_disc_cfg cc = ca;
		struct om_disc d32;
		struct om_identity ids[33];
		char first_hex[OM_ID_HEX_LEN];
		char last_hex[OM_ID_HEX_LEN];

		CHECK(om_disc_init(&d32, &cc, &ia) == 0);
		for (int i = 0; i < 33; i++) {
			char tag[8];

			snprintf(tag, sizeof(tag), "e%d", i);
			mkident(&ids[i], tag);
			n = om_disc_build_packet(&(struct om_disc){ .cfg = cc,
					.id = &ids[i] }, pkt, sizeof(pkt),
					(uint64_t)now);
			CHECK(n >= OM_MIN_LEN);
			CHECK(om_disc_handle_packet(&d32, pkt, n, "10.0.0.1",
						    now + i) == 0);
			CHECK(d32.n_nodes <= OM_DISC_MAX_NODES);
		}
		CHECK(d32.n_nodes == OM_DISC_MAX_NODES);
		om_id_to_hex(ids[0].id, first_hex);
		om_id_to_hex(ids[32].id, last_hex);
		CHECK(find_node_hex(&d32, first_hex) == NULL);
		CHECK(find_node_hex(&d32, last_hex) != NULL);
		om_disc_free(&d32);
	}

	/* 13. socket loopback: two endpoints discover each other */
	{
		struct om_disc_cfg la = ca, lb = ca;

		la.listen_port = 17801;
		la.dest_port = 17802;
		lb.listen_port = 17802;
		lb.dest_port = 17801;

		CHECK(om_disc_init(&da, &la, &ia) == 0);
		da.on_new = count_new;
		CHECK(om_disc_init(&db, &lb, &ib) == 0);
		db.on_new = count_new;

		CHECK(om_disc_send(&db) == 0);
		om_disc_recv_ready(&da);
		CHECK(da.n_nodes == 1);
		CHECK(new_calls == 3);

		CHECK(om_disc_send(&da) == 0);
		om_disc_recv_ready(&db);
		CHECK(db.n_nodes == 1);
		CHECK(new_calls == 4);

		om_disc_free(&da);
		om_disc_free(&db);
	}

	printf("test_discovery: %d checks passed\n", checks);
	return 0;
}
